public enum AppUniFFISemanticComputeBackend: Sendable, Equatable {
    case metal
    case cpuFallback
    case deterministicTestDouble
}

public struct AppUniFFISemanticModelInfo: Sendable, Equatable {
    public var modelId: String
    public var modelRevision: String
    public var ggufFilename: String
    public var expectedBytes: UInt64
    public var expectedSha256: String
    public var llamaCppTag: String
    public var llamaCppCommit: String
    public var modelFingerprint: UInt64
    public var backend: AppUniFFISemanticComputeBackend

    public init(
        modelId: String,
        modelRevision: String,
        ggufFilename: String,
        expectedBytes: UInt64,
        expectedSha256: String,
        llamaCppTag: String,
        llamaCppCommit: String,
        modelFingerprint: UInt64,
        backend: AppUniFFISemanticComputeBackend
    ) {
        self.modelId = modelId
        self.modelRevision = modelRevision
        self.ggufFilename = ggufFilename
        self.expectedBytes = expectedBytes
        self.expectedSha256 = expectedSha256
        self.llamaCppTag = llamaCppTag
        self.llamaCppCommit = llamaCppCommit
        self.modelFingerprint = modelFingerprint
        self.backend = backend
    }
}

