/// Protocol matching the generated `UniFFISemanticSearchEngine` object from `uniffi_api/semantic_search.rs`.
public protocol UniFFISemanticSearchEngineBindingProtocol: Sendable {
    func modelState() -> AppUniFFISemanticModelState
    func prepareModelRuntime() -> AppUniFFISemanticModelState
    func registerScope(descriptor: AppUniFFISemanticScopeDescriptor) -> Bool
    func revokeScope(scopeId: String) -> Bool
    func startDirectoryIndexing(scopeId: String) -> AppUniFFISemanticIndexProgress
    func cancelIndexing(scopeId: String)
    func scopeProgress(scopeId: String) -> AppUniFFISemanticIndexProgress?
    func upsertArchiveEntries(
        scopeId: String,
        entries: [AppUniFFISemanticArchiveEntryInput]
    ) -> AppUniFFISemanticIndexProgress
    func removeIndexedFile(scopeId: String, relativePath: String) -> Bool
    func search(request: AppUniFFISemanticSearchRequest) -> AppUniFFISemanticSearchResponse
    func cancelSearch(requestId: UInt64)
    func buildOpenRequest(hit: AppUniFFISemanticSearchHit) -> AppUniFFISemanticOpenRequest
}

public extension UniFFISemanticSearchEngineBindingProtocol {
    func prepareModelRuntime() -> AppUniFFISemanticModelState { modelState() }
}

#if TTZIP_UNIFFI_SEMANTIC_SEARCH_LINKED
extension UniFFISemanticSearchEngine: UniFFISemanticSearchEngineBindingProtocol {}
#endif

/// Production UniFFI bridge forwarding Swift semantic search operations to Rust `UniFFISemanticSearchEngine`.
/// When `TTZIP_UNIFFI_SEMANTIC_SEARCH_LINKED` is active, instantiates `UniFFISemanticSearchEngine(storageDir:)`
/// and forwards all 11 operations 1-to-1.
/// When not yet linked in `TTZipCore`, explicitly reports `.engineUnlinked` (`degradedLexicalOnly: false`,
/// `isEngineLinked: false`) and NEVER masquerades as a successful lexical-only degradation.
public actor UniFFIRustSemanticCoreBridge: RustSemanticCoreBridging {
    public static let unlinkedReasonMessage =
        "ENGINE_UNLINKED: UniFFISemanticSearchEngine bindings not yet generated in TTZipCore"

    private let blockingExecutor = SemanticCoreBlockingExecutor()
    private let nativeQueueWaitObserver: (@Sendable (String) async -> Void)?

    var pendingNativeAdmissionCount: Int { blockingExecutor.pendingAdmissionCount }
    private let storageDirectory: URL
    private let engineFactory: (@Sendable (URL) -> (any UniFFISemanticSearchEngineBindingProtocol)?)?
    private var retainedInjectedEngine: (any UniFFISemanticSearchEngineBindingProtocol)?
    private var currentSession: SemanticBindingSessionBox?
    private var retiringSessions: [UInt64: SemanticBindingSessionBox] = [:]
    private var nextGeneration: UInt64 = 1
    private var transitionTicket: UInt64 = 0
    private var activeScopeIds: Set<String> = []
    private var activeSearchRequestIds: Set<UInt64> = []
    private var cancelledRequestIds: Set<UInt64> = []
    private var isResetDraining: Bool = false
    private var isShutDown: Bool = false

    public var isTerminated: Bool {
        isShutDown
    }

    public var hasActiveBinding: Bool {
        (currentSession?.hasActiveEngine == true) || !retiringSessions.isEmpty
    }

    public var isDraining: Bool {
        isResetDraining || !retiringSessions.isEmpty
    }

    public init(storageDirectory: URL) {
        self.storageDirectory = storageDirectory
        self.nativeQueueWaitObserver = nil
        self.retainedInjectedEngine = nil
        #if TTZIP_UNIFFI_SEMANTIC_SEARCH_LINKED
        let factory: @Sendable (URL) -> (any UniFFISemanticSearchEngineBindingProtocol)? = { dir in
            UniFFISemanticSearchEngine(storageDir: dir.path)
        }
        self.engineFactory = factory
        if let engine = factory(storageDirectory) {
            self.currentSession = SemanticBindingSessionBox(generation: 1, engine: engine)
            self.nextGeneration = 2
        }
        #else
        self.engineFactory = nil
        #endif
    }

    public init(
        storageDirectory: URL,
        uniffiEngine: (any UniFFISemanticSearchEngineBindingProtocol)?
    ) {
        self.storageDirectory = storageDirectory
        self.nativeQueueWaitObserver = nil
        self.engineFactory = nil
        self.retainedInjectedEngine = uniffiEngine
        if let engine = uniffiEngine {
            self.currentSession = SemanticBindingSessionBox(generation: 1, engine: engine)
            self.nextGeneration = 2
        }
    }

    public init(
        storageDirectory: URL,
        engineFactory: @escaping @Sendable (URL) -> (any UniFFISemanticSearchEngineBindingProtocol)?
    ) {
        self.storageDirectory = storageDirectory
        self.nativeQueueWaitObserver = nil
        self.engineFactory = engineFactory
        self.retainedInjectedEngine = nil
        if let engine = engineFactory(storageDirectory) {
            self.currentSession = SemanticBindingSessionBox(generation: 1, engine: engine)
            self.nextGeneration = 2
        }
    }

    init(
        storageDirectory: URL,
        engineFactory: @escaping @Sendable (URL) -> (any UniFFISemanticSearchEngineBindingProtocol)?,
        beforeNativeQueueWait: @escaping @Sendable (String) async -> Void
    ) {
        self.storageDirectory = storageDirectory
        self.nativeQueueWaitObserver = beforeNativeQueueWait
        self.engineFactory = engineFactory
        self.retainedInjectedEngine = nil
        if let engine = engineFactory(storageDirectory) {
            self.currentSession = SemanticBindingSessionBox(generation: 1, engine: engine)
            self.nextGeneration = 2
        }
    }

    private func retireCurrentSession() {
        guard let session = currentSession else { return }
        currentSession = nil
        blockingExecutor.cancelGeneration(session.generation)
        retiringSessions[session.generation] = session
        session.beginRetire(
            activeScopeIds: activeScopeIds,
            activeSearchRequestIds: activeSearchRequestIds
        )
    }

    private func drainAllRetiringSessions() async {
        while let (generation, session) = retiringSessions.first {
            await session.waitUntilDrained()
            if retiringSessions[generation] === session, !session.hasActiveEngine {
                retiringSessions.removeValue(forKey: generation)
            }
        }
    }

    private func executeAcceptedOnNativeLane<T: Sendable>(
        session: SemanticBindingSessionBox,
        ticket: SemanticCoreBlockingExecutor.Ticket,
        ensurePrepared: Bool,
        cancelled: T,
        operation: @escaping @Sendable (any UniFFISemanticSearchEngineBindingProtocol) -> T
    ) async -> T {
        guard session.tryAcceptOperation() else {
            blockingExecutor.discard(ticket)
            return cancelled
        }
        defer { session.finishAcceptedOperation() }
        let result = await blockingExecutor.run(
            ticket: ticket,
            cancelled: cancelled
        ) {
            session.executeOnNativeLane(ensurePrepared: ensurePrepared, operation) ?? cancelled
        }
        return (isShutDown || session.isRetiredOrDestroyed) ? cancelled : result
    }

    public func resetEngine() async throws {
        transitionTicket &+= 1
        let myTicket = transitionTicket
        isResetDraining = true
        blockingExecutor.cancelAll()
        cancelledRequestIds.removeAll()
        retireCurrentSession()
        await drainAllRetiringSessions()
        guard !isShutDown, transitionTicket == myTicket else {
            if transitionTicket == myTicket { isResetDraining = false }
            return
        }
        activeScopeIds.removeAll()
        activeSearchRequestIds.removeAll()
        if let engine = engineFactory?(storageDirectory) ?? retainedInjectedEngine {
            let generation = nextGeneration
            nextGeneration &+= 1
            currentSession = SemanticBindingSessionBox(generation: generation, engine: engine)
        } else {
            currentSession = nil
        }
        isResetDraining = false
    }

    @discardableResult
    public func shutdown() async -> Bool {
        isShutDown = true
        isResetDraining = true
        retainedInjectedEngine = nil
        transitionTicket &+= 1
        blockingExecutor.cancelAll()
        cancelledRequestIds.removeAll()
        retireCurrentSession()
        await drainAllRetiringSessions()
        activeScopeIds.removeAll()
        activeSearchRequestIds.removeAll()
        isResetDraining = false
        return isShutDown && !hasActiveBinding
    }

    public func modelState() async -> SemanticModelInstallState {
        if isShutDown {
            return hasActiveBinding
                ? .failed(reason: "Bridge shut down without releasing UniFFI engine binding")
                : .notInstalled
        }
        guard let session = currentSession else {
            return isDraining ? .notInstalled : .engineUnlinked(reason: Self.unlinkedReasonMessage)
        }
        guard session.tryAcceptOperation() else { return .notInstalled }
        defer { session.finishAcceptedOperation() }
        guard let raw = session.executeDirect({ $0.modelState() }) else { return .notInstalled }
        return Self.mapModelState(raw)
    }

    public func prepareModelRuntime() async -> SemanticModelInstallState {
        guard !isShutDown, !isDraining, let session = currentSession else {
            return (isShutDown || isDraining) ? .notInstalled : await modelState()
        }
        guard session.tryAcceptOperation() else { return .notInstalled }
        defer { session.finishAcceptedOperation() }
        let ticket = blockingExecutor.admit(generation: session.generation, key: "prepare")
        let state = await blockingExecutor.run(
            ticket: ticket,
            cancelled: SemanticModelInstallState.notInstalled
        ) {
            guard let raw = session.prepareOnNativeLane() else { return .notInstalled }
            return Self.mapModelState(raw)
        }
        return (isShutDown || session.isRetiredOrDestroyed) ? .notInstalled : state
    }

    public func registerScope(_ descriptor: SemanticScopeDescriptor) async -> Bool {
        guard !isShutDown, !isDraining, let session = currentSession else { return false }
        let uniffiScope = Self.toUniFFIScope(descriptor)
        let ticket = blockingExecutor.admit(generation: session.generation, key: "scope:\(descriptor.scopeId)")
        let registered = await executeAcceptedOnNativeLane(
            session: session,
            ticket: ticket,
            ensurePrepared: false,
            cancelled: false
        ) { engine in
            engine.registerScope(descriptor: uniffiScope)
        }
        if registered { activeScopeIds.insert(descriptor.scopeId) }
        return registered
    }

    public func revokeScope(scopeId: String) async -> Bool {
        guard !isShutDown, !isDraining, let session = currentSession else { return false }
        activeScopeIds.remove(scopeId)
        blockingExecutor.cancel(key: "scope:\(scopeId)")
        let ticket = blockingExecutor.admit(generation: session.generation, key: "revoke:\(scopeId)")
        return await executeAcceptedOnNativeLane(
            session: session,
            ticket: ticket,
            ensurePrepared: false,
            cancelled: false
        ) { engine in
            engine.revokeScope(scopeId: scopeId)
        }
    }

    public func startDirectoryIndexing(scopeId: String) async -> SemanticIndexProgress {
        let cancelled = Self.cancelledProgress(scopeId: scopeId)
        if isShutDown || isDraining { return cancelled }
        guard let session = currentSession else { return Self.unlinkedProgress(scopeId: scopeId) }
        activeScopeIds.insert(scopeId)
        let ticket = blockingExecutor.admit(generation: session.generation, key: "scope:\(scopeId)")
        return await executeAcceptedOnNativeLane(
            session: session,
            ticket: ticket,
            ensurePrepared: true,
            cancelled: cancelled
        ) { engine in
            Self.mapProgress(engine.startDirectoryIndexing(scopeId: scopeId))
        }
    }

    public func cancelIndexing(scopeId: String) async {
        blockingExecutor.cancel(key: "scope:\(scopeId)")
        currentSession?.cancelIndexingIfRunning(scopeId: scopeId)
        for session in retiringSessions.values {
            session.cancelIndexingIfRunning(scopeId: scopeId)
        }
    }

    public func scopeProgress(scopeId: String) async -> SemanticIndexProgress? {
        if isShutDown || isDraining { return nil }
        guard let session = currentSession else { return Self.unlinkedProgress(scopeId: scopeId) }
        guard session.tryAcceptOperation() else { return nil }
        defer { session.finishAcceptedOperation() }
        return session.executeDirect({ $0.scopeProgress(scopeId: scopeId) })?.map(Self.mapProgress)
    }

    public func upsertArchiveEntries(
        scopeId: String,
        entries: [(entryPath: String, data: Data, mtimeNs: Int64)]
    ) async -> SemanticIndexProgress {
        let total = UInt32(entries.count)
        let cancelled = Self.cancelledProgress(scopeId: scopeId, totalFiles: total)
        if isShutDown || isDraining { return cancelled }
        guard let session = currentSession else {
            return Self.unlinkedProgress(scopeId: scopeId, totalFiles: total)
        }
        activeScopeIds.insert(scopeId)
        let uniffiEntries = entries.map {
            AppUniFFISemanticArchiveEntryInput(
                entryPath: $0.entryPath,
                bytes: $0.data,
                mtimeNs: $0.mtimeNs
            )
        }
        let ticket = blockingExecutor.admit(generation: session.generation, key: "scope:\(scopeId)")
        return await executeAcceptedOnNativeLane(
            session: session,
            ticket: ticket,
            ensurePrepared: true,
            cancelled: cancelled
        ) { engine in
            Self.mapProgress(engine.upsertArchiveEntries(scopeId: scopeId, entries: uniffiEntries))
        }
    }

    public func removeIndexedFile(scopeId: String, relativePath: String) async -> Bool {
        guard !isShutDown, !isDraining, let session = currentSession else { return false }
        let ticket = blockingExecutor.admit(generation: session.generation, key: "scope:\(scopeId)")
        return await executeAcceptedOnNativeLane(
            session: session,
            ticket: ticket,
            ensurePrepared: false,
            cancelled: false
        ) { engine in
            engine.removeIndexedFile(scopeId: scopeId, relativePath: relativePath)
        }
    }

    public func search(_ request: SemanticSearchRequest) async -> SemanticSearchResponse {
        if isShutDown || isDraining {
            return Self.cancelledSearchResponse(request: request, isEngineLinked: !isShutDown)
        }
        if cancelledRequestIds.contains(request.requestId) {
            currentSession?.cancelSearchIfRunning(requestId: request.requestId)
            return Self.cancelledSearchResponse(
                request: request,
                isEngineLinked: currentSession != nil,
                unlinkedReason: currentSession == nil ? Self.unlinkedReasonMessage : nil
            )
        }
        guard let session = currentSession else {
            return Self.unlinkedSearchResponse(request: request)
        }
        activeSearchRequestIds.insert(request.requestId)
        defer { activeSearchRequestIds.remove(request.requestId) }
        let uniffiReq = Self.toUniFFISearchRequest(request)
        let cancelled = AppUniFFISemanticSearchResponse(
            requestId: request.requestId, windowId: request.windowId,
            isCancelled: true, degradedLexicalOnly: false, hits: []
        )
        let ticket = blockingExecutor.admit(generation: session.generation, key: "search:\(request.requestId)")
        if let observer = nativeQueueWaitObserver {
            await observer(ticket.key)
        }
        let raw = await executeAcceptedOnNativeLane(
            session: session,
            ticket: ticket,
            ensurePrepared: true,
            cancelled: cancelled
        ) { engine in
            engine.search(request: uniffiReq)
        }
        if isShutDown || session.isRetiredOrDestroyed || cancelledRequestIds.contains(request.requestId) {
            return SemanticSearchResponse(
                requestId: request.requestId,
                windowId: request.windowId,
                isCancelled: true,
                degradedLexicalOnly: raw.degradedLexicalOnly,
                hits: [],
                isEngineLinked: true,
                engineUnlinkedReason: nil
            )
        }
        return Self.mapSearchResponse(raw)
    }

    public func cancelSearch(requestId: UInt64) async {
        blockingExecutor.cancel(key: "search:\(requestId)")
        cancelledRequestIds.insert(requestId)
        currentSession?.cancelSearchIfRunning(requestId: requestId)
        for session in retiringSessions.values {
            session.cancelSearchIfRunning(requestId: requestId)
        }
    }

    public nonisolated func buildOpenRequest(for hit: SemanticSearchHit) -> SemanticOpenRequest {
        SemanticOpenRequest(
            scopeId: hit.scopeId,
            sourceKind: hit.sourceKind,
            outerPath: hit.resolvedOuterFilePath,
            archiveEntryPath: hit.archiveEntryPath,
            lineNumber: hit.lineStart
        )
    }

    private static func cancelledSearchResponse(
        request: SemanticSearchRequest,
        isEngineLinked: Bool,
        unlinkedReason: String? = nil
    ) -> SemanticSearchResponse {
        SemanticSearchResponse(
            requestId: request.requestId,
            windowId: request.windowId,
            isCancelled: true,
            degradedLexicalOnly: false,
            hits: [],
            isEngineLinked: isEngineLinked,
            engineUnlinkedReason: unlinkedReason
        )
    }

    private static func unlinkedSearchResponse(
        request: SemanticSearchRequest
    ) -> SemanticSearchResponse {
        SemanticSearchResponse(
            requestId: request.requestId,
            windowId: request.windowId,
            isCancelled: false,
            degradedLexicalOnly: false,
            hits: [],
            isEngineLinked: false,
            engineUnlinkedReason: Self.unlinkedReasonMessage
        )
    }
}
